import { Controller, Patch, Post, Get, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ACCOUNTANT = '예산·회계 담당자';
const EMPLOYEE = '임직원';
const EVIDENCE_TYPES = ['통장', '카드', '현금영수증', '전자세금계산서'];

// 가정: 주요 변경 이력(변경 일시·변경자·변경내용)은 이력 테이블이 스키마에 없어 저장하지 않는다. 공통 이력 모듈이 맡는다고 가정한다.

function pathId(value: unknown): string {
  const text = typeof value === 'string' ? value : '';
  if (!/^[0-9]{1,18}$/.test(text)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '전표 ID 형식이 올바르지 않습니다.');
  }
  return text;
}

@Controller('api/v1')
export class FnSfr00801Controller {
  @Patch('/journal-vouchers/:journalVoucherId')
  async updateJournalVoucher(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ACCOUNTANT);
    const id = pathId(req.params['journalVoucherId']);
    const data = checks.inputOf(req.body);
    const itemId = data['managementItemId'];
    const itemValue = data['managementItemValue'];
    if (typeof itemId !== 'number' || !Number.isInteger(itemId) || itemId <= 0) {
      throw new ApiError(400, 'VALIDATION_FAILED', '관리항목을 선택해 주세요.');
    }
    if (typeof itemValue !== 'string' || itemValue.trim() === '' || itemValue.length > 200) {
      throw new ApiError(400, 'VALIDATION_FAILED', '관리항목 값을 200자 이내로 입력해 주세요.');
    }
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT status FROM journal_voucher WHERE journal_voucher_id = CAST(:id AS bigint)',
        { id },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'JOURNAL_VOUCHER_NOT_FOUND', '전표를 찾을 수 없습니다.');
      }
      if (found[0]['status'] === '마감') {
        throw new ApiError(409, 'JOURNAL_VOUCHER_CLOSED', '마감·확정된 전표는 수정할 수 없습니다. 승인 해제 등 정해진 절차를 거쳐 주세요.');
      }
      const item = await db.query(
        'SELECT management_item_id FROM management_item WHERE management_item_id = CAST(:itemId AS bigint)',
        { itemId },
      );
      if (item.length === 0) {
        throw new ApiError(404, 'NOT_FOUND', '관리항목을 찾을 수 없습니다.');
      }
      await db.execute(
        'UPDATE voucher_line SET management_item_id = CAST(:itemId AS bigint), management_item_value = :itemValue, updated_at = now() WHERE journal_voucher_id = CAST(:id AS bigint)',
        { itemId, itemValue: itemValue.trim(), id },
      );
      await db.execute(
        'UPDATE journal_voucher SET updated_at = now() WHERE journal_voucher_id = CAST(:id AS bigint)',
        { id },
      );
      const rows = await db.query(
        'SELECT journal_voucher_id AS "journalVoucherId" FROM journal_voucher WHERE journal_voucher_id = CAST(:id AS bigint)',
        { id },
      );
      return rows[0];
    });
  }

  @Post('/journal-vouchers/change-evidence')
  @HttpCode(200)
  async changeJournalVoucherEvidence(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ACCOUNTANT);
    const data = checks.inputOf(req.body);
    const idList = data['journalVoucherIds'];
    const evidenceType = data['evidenceType'];
    if (!Array.isArray(idList) || idList.length === 0) {
      throw new ApiError(400, 'VALIDATION_FAILED', '변경할 전표를 선택해 주세요.');
    }
    const ids: string[] = [];
    for (const raw of idList) {
      if (typeof raw !== 'number' || !Number.isInteger(raw) || raw <= 0) {
        throw new ApiError(400, 'VALIDATION_FAILED', '전표 ID 형식이 올바르지 않습니다.');
      }
      ids.push(String(raw));
    }
    if (typeof evidenceType !== 'string' || evidenceType === '') {
      throw new ApiError(400, 'VALIDATION_FAILED', '증빙 유형을 선택해 주세요.');
    }
    if (!EVIDENCE_TYPES.includes(evidenceType)) {
      throw new ApiError(422, 'EVIDENCE_TYPE_INVALID', '증빙 유형은 통장, 카드, 현금영수증, 전자세금계산서만 허용합니다.');
    }
    return transaction(async (db) => {
      const closed = await db.query(
        'SELECT journal_voucher_id FROM journal_voucher WHERE journal_voucher_id = ANY(CAST(:ids AS bigint[])) AND status = :closed',
        { ids, closed: '마감' },
      );
      if (closed.length > 0) {
        throw new ApiError(409, 'JOURNAL_VOUCHER_CLOSED', '마감·확정된 전표가 포함되어 있어 변경할 수 없습니다.');
      }
      const changed = await db.execute(
        'UPDATE journal_voucher SET evidence_type = :evidenceType, updated_at = now() WHERE journal_voucher_id = ANY(CAST(:ids AS bigint[]))',
        { evidenceType, ids },
      );
      return { changedCount: changed };
    });
  }

  @Post('/journal-vouchers/:journalVoucherId/release-approval')
  @HttpCode(200)
  async releaseJournalVoucherApproval(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ACCOUNTANT);
    const id = pathId(req.params['journalVoucherId']);
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT status FROM journal_voucher WHERE journal_voucher_id = CAST(:id AS bigint)',
        { id },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'JOURNAL_VOUCHER_NOT_FOUND', '전표를 찾을 수 없습니다.');
      }
      if (found[0]['status'] !== '승인') {
        throw new ApiError(409, 'JOURNAL_VOUCHER_NOT_APPROVED', '승인 상태인 전표만 승인 해제할 수 있습니다.');
      }
      await db.execute(
        'UPDATE journal_voucher SET status = :status, updated_at = now() WHERE journal_voucher_id = CAST(:id AS bigint)',
        { status: '승인해제', id },
      );
      const rows = await db.query(
        'SELECT status FROM journal_voucher WHERE journal_voucher_id = CAST(:id AS bigint)',
        { id },
      );
      return rows[0];
    });
  }

  @Get('/journal-vouchers/:journalVoucherId/print')
  async printJournalVoucher(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ACCOUNTANT, EMPLOYEE);
    const id = pathId(req.params['journalVoucherId']);
    checks.queryOf(req.query);
    return transaction(async (db) => {
      const rows = await db.query(
        'SELECT voucher_no AS "voucherNo", voucher_date AS "voucherDate", debit_total AS "debitTotal", credit_total AS "creditTotal" FROM journal_voucher WHERE journal_voucher_id = CAST(:id AS bigint)',
        { id },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'JOURNAL_VOUCHER_NOT_FOUND', '전표를 찾을 수 없습니다.');
      }
      return rows[0];
    });
  }
}

