import { useState } from 'react';
import {
  call, Badge, Num, DateText, Band, DataTable, Drawer, Pairs, Tiles, Form, Field,
  TextInput, Select, LookupSelect, RefName,
} from '../kit';
import type { PageProps, Row } from '../kit';

const EVIDENCE_OPTIONS: [string, string][] = [
  ['통장', '통장'],
  ['카드', '카드'],
  ['현금영수증', '현금영수증'],
  ['전자세금계산서', '전자세금계산서'],
];

function voucherPath(id: unknown, tail?: string): string {
  const parts = ['/journal-vouchers', String(id)];
  if (tail) {
    parts.push(tail);
  }
  return parts.join('/');
}

type Mode = '' | 'create' | 'manage' | 'evidence' | 'print';

export default function FnSfr00801Page({ role, notify }: PageProps) {
  // 조회 API가 없어 이 화면에서 입력·처리한 전표를 목록으로 보인다.
  const [rows, setRows] = useState<Row[]>([]);
  const [mode, setMode] = useState<Mode>('');
  const [target, setTarget] = useState<Row | null>(null);
  const [selected, setSelected] = useState<number[]>([]);
  const [resolutionId, setResolutionId] = useState<number | string>('');
  const [itemId, setItemId] = useState<number | string>('');
  const [itemValue, setItemValue] = useState('');
  const [evidenceType, setEvidenceType] = useState('');
  const [printData, setPrintData] = useState<Row | null>(null);

  const close = () => {
    setMode('');
    setTarget(null);
    setPrintData(null);
  };

  const patchRow = (id: unknown, change: Row) => {
    setRows((list) => list.map((r) => (r['journalVoucherId'] === id ? { ...r, ...change } : r)));
  };

  const toggle = (id: number) => {
    setSelected((list) => (list.includes(id) ? list.filter((v) => v !== id) : [...list, id]));
  };

  const submitCreate = async () => {
    if (resolutionId === '' || typeof resolutionId !== 'number') {
      throw new Error('원천 결의서를 선택해 주세요.');
    }
    const res = await call<Row>('POST', '/journal-vouchers', role, { expenseResolutionId: resolutionId });
    setRows((list) => [{ ...res, status: '승인', expenseResolutionId: resolutionId }, ...list]);
    notify('전표를 입력했습니다.');
    setResolutionId('');
    close();
  };

  const submitManage = async () => {
    if (itemId === '' || typeof itemId !== 'number') {
      throw new Error('관리항목을 선택해 주세요.');
    }
    if (itemValue.trim() === '') {
      throw new Error('관리항목 값을 입력해 주세요.');
    }
    await call('PATCH', voucherPath(target?.['journalVoucherId']), role, {
      managementItemId: itemId,
      managementItemValue: itemValue.trim(),
    });
    notify('관리항목을 변경했습니다.');
    setItemId('');
    setItemValue('');
    close();
  };

  const submitEvidence = async () => {
    if (selected.length === 0) {
      throw new Error('변경할 전표를 선택해 주세요.');
    }
    if (evidenceType === '') {
      throw new Error('증빙 유형을 선택해 주세요.');
    }
    const res = await call<Row>('POST', '/journal-vouchers/change-evidence', role, {
      journalVoucherIds: selected,
      evidenceType,
    });
    setRows((list) => list.map((r) => (
      selected.includes(r['journalVoucherId'] as number) ? { ...r, evidenceType } : r
    )));
    notify('증빙내역을 ' + String(res['changedCount']) + '건 변경했습니다.');
    setSelected([]);
    setEvidenceType('');
    close();
  };

  const release = async (row: Row) => {
    try {
      const res = await call<Row>('POST', voucherPath(row['journalVoucherId'], 'release-approval'), role, {});
      patchRow(row['journalVoucherId'], { status: res['status'] });
      notify('승인을 해제했습니다.');
    } catch (e) {
      notify(e instanceof Error ? e.message : '승인 해제에 실패했습니다.');
    }
  };

  const openPrint = async (row: Row) => {
    try {
      const res = await call<Row>('GET', voucherPath(row['journalVoucherId'], 'print'), role);
      patchRow(row['journalVoucherId'], res);
      setTarget(row);
      setPrintData(res);
      setMode('print');
    } catch (e) {
      notify(e instanceof Error ? e.message : '전표를 출력하지 못했습니다.');
    }
  };

  const approvedCount = rows.filter((r) => r['status'] === '승인').length;
  const releasedCount = rows.filter((r) => r['status'] === '승인해제').length;

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>처리 현황</h2>
        <Tiles
          items={[
            ['처리한 전표', <Num value={rows.length} />],
            ['승인', <Num value={approvedCount} />],
            ['승인해제', <Num value={releasedCount} />],
            ['선택한 전표', <Num value={selected.length} />],
          ]}
        />
      </section>
      <section className="box span-12">
        <h2>전표</h2>
        <Band total={rows.length}>
          <button type="button" onClick={() => setMode('create')}>전표 입력</button>
          <button type="button" onClick={() => setMode('evidence')}>증빙내역 일괄 변경</button>
        </Band>
        <DataTable
          rows={rows}
          empty="이 화면에서 처리한 전표가 없습니다. 전표를 입력해 주세요."
          columns={[
            {
              key: 'select',
              label: '선택',
              render: (r) => (
                <input
                  type="checkbox"
                  checked={selected.includes(r['journalVoucherId'] as number)}
                  onChange={() => toggle(r['journalVoucherId'] as number)}
                  onClick={(e) => e.stopPropagation()}
                />
              ),
            },
            { key: 'voucherNo', label: '전표번호' },
            {
              key: 'expenseResolutionId',
              label: '원천 결의서',
              render: (r) => <RefName table="expense_resolution" role={role} value={r['expenseResolutionId']} />,
            },
            { key: 'voucherDate', label: '전표일자', render: (r) => <DateText value={r['voucherDate']} /> },
            { key: 'evidenceType', label: '증빙 유형' },
            { key: 'debitTotal', label: '차변 합계', render: (r) => <Num value={r['debitTotal']} /> },
            { key: 'creditTotal', label: '대변 합계', render: (r) => <Num value={r['creditTotal']} /> },
            { key: 'status', label: '전표 상태', render: (r) => <Badge value={r['status']} /> },
            {
              key: 'actions',
              label: '처리',
              render: (r) => (
                <span onClick={(e) => e.stopPropagation()}>
                  {r['status'] !== '마감' && (
                    <button
                      type="button"
                      onClick={() => {
                        setTarget(r);
                        setMode('manage');
                      }}
                    >
                      관리항목 변경
                    </button>
                  )}
                  {r['status'] === '승인' && (
                    <button type="button" onClick={() => release(r)}>승인 해제</button>
                  )}
                  <button type="button" onClick={() => openPrint(r)}>출력</button>
                </span>
              ),
            },
          ]}
        />
      </section>

      {mode === 'create' && (
        <Drawer title="전표 입력" onClose={close}>
          <Form onSubmit={submitCreate} submit="전표 생성" note="승인된 결의서로 분개를 생성하고 전표를 만듭니다.">
            <Field label="원천 결의서" required wide>
              <LookupSelect
                table="expense_resolution"
                role={role}
                value={resolutionId}
                onChange={setResolutionId}
                placeholder="결의서 선택"
              />
            </Field>
          </Form>
        </Drawer>
      )}

      {mode === 'manage' && target && (
        <Drawer title="전표 관리항목 변경" onClose={close}>
          <Form onSubmit={submitManage} submit="변경">
            <Field label="전표번호" wide>
              <TextInput value={target['voucherNo'] ?? ''} onChange={() => undefined} />
            </Field>
            <Field label="관리항목" required wide>
              <LookupSelect
                table="management_item"
                role={role}
                value={itemId}
                onChange={setItemId}
                placeholder="관리항목 선택"
              />
            </Field>
            <Field label="관리항목 값" required wide>
              <TextInput value={itemValue} onChange={setItemValue} />
            </Field>
          </Form>
        </Drawer>
      )}

      {mode === 'evidence' && (
        <Drawer title="증빙내역 일괄 변경" onClose={close}>
          <Form
            onSubmit={submitEvidence}
            submit="일괄 변경"
            note={'목록에서 선택한 전표 ' + String(selected.length) + '건에 적용합니다.'}
          >
            <Field label="증빙 유형" required wide>
              <Select value={evidenceType} onChange={setEvidenceType} options={EVIDENCE_OPTIONS} />
            </Field>
          </Form>
        </Drawer>
      )}

      {mode === 'print' && target && printData && (
        <Drawer title="전표 출력" onClose={close}>
          <Pairs
            items={[
              ['전표번호', String(printData['voucherNo'] ?? '')],
              ['전표일자', <DateText value={printData['voucherDate']} />],
              ['차변 합계', <Num value={printData['debitTotal']} />],
              ['대변 합계', <Num value={printData['creditTotal']} />],
            ]}
          />
          <button type="button" onClick={() => window.print()}>인쇄</button>
        </Drawer>
      )}
    </div>
  );
}
